	case "shexp.up":
		return 2 * float64(tok) * ff * embd * 2 / s / 1e9, float64(shUpPair) / s / 1e9
	case "shexp.down":
		return 2 * float64(tok) * embd * ff / s / 1e9, float64(shDown) / s / 1e9
