func moeBM(k MoEKernel) int {
	switch k {
	case MoEM1, MoEN1M1, MoEN2M1:
		return 16
	case MoEM2, MoEW2M1:
		return 32
	case MoEM4, MoEW4M1:
		return 64
	}
